sys_variable_value.value:
(function execute(inputs, outputs) {
    var T = 'x_2078844_gstin_0_gst_compliance_profile';
    var p = new GlideRecord(T);
    p.addQuery('supplier', inputs.supplier_id);
    p.orderByDesc('sys_created_on');
    p.setLimit(1);
    p.query();
    if (p.next()) {
        outputs.profile = p.getUniqueValue();
        outputs.profile_id = p.getUniqueValue();
        outputs.created = false;
        return;
    }
    // No profile yet: create a Pending placeholder so the GST gate always has a record to wait on.
    var n = new GlideRecord(T);
    n.initialize();
    n.setValue('supplier', inputs.supplier_id);
    n.setValue('result', 'pending');
    n.setValue('result_reason', 'Waiting for GST details from the supplier (created by onboarding playbook)');
    var c = new GlideRecord('sn_slm_case');
    c.addQuery('supplier', inputs.supplier_id);
    c.addQuery('case_type', 'supplier_onboarding');
    c.addQuery('active', true);
    c.orderByDesc('sys_created_on');
    c.setLimit(1);
    c.query();
    if (c.next()) n.setValue('onboarding_case', c.getUniqueValue());
    var newId = n.insert();
    outputs.profile = newId;
    outputs.profile_id = newId;
    outputs.created = true;
})(inputs, outputs);

